  'tip.stateCost': {
    en: `Just the pay itself. The Chamber pays nothing extra on top, as an employer would. MPs' pensions come from their own 8.80% and from the Chamber's budget.`,
    nl: `Alleen het loon zelf. De Kamer betaalt er niets bovenop, zoals een werkgever zou doen. De pensioenen van parlementsleden komen uit hun eigen 8,80% en uit de begroting van de Kamer.`,
    fr: `Seulement l'indemnité elle-même. La Chambre ne paie rien en plus, comme le ferait un employeur. Les retraites des députés viennent de leurs propres 8,80% et du budget de la Chambre.`,
  },
  'tip.minEr': { en: `Nothing is paid on top of an MP's or minister's pay, unlike an employer does for a worker.`, nl: `Er wordt niets betaald bovenop het loon van een parlementslid of minister, anders dan een werkgever doet voor een werknemer.`, fr: `Rien n'est payé en plus de l'indemnité d'un député ou d'un ministre, contrairement à ce que fait un employeur pour un salarié.` },
  'tip.minEeMp': {
    en: `Taken from the MP's pay before income tax: 8.80% for the pension, 784.14 € a month for a payment when they leave (each year served gives back 80% of one month's pay), and 526.66 € a month for an extra health fund.`,
    nl: `Afgehouden van het loon vóór de inkomstenbelasting: 8,80% voor het pensioen, 784,14 € per maand voor een uitkering bij hun vertrek (elk jaar in functie geeft 80% van een maandloon terug), en 526,66 € per maand voor een aanvullend ziekenfonds.`,
    fr: `Retenus sur l'indemnité avant impôt : 8,80% pour la retraite, 784,14 € par mois pour une somme versée au départ (chaque année de mandat rend 80% d'un mois d'indemnité), et 526,66 € par mois pour une caisse de santé complémentaire.`,
  },
  'tip.minEeTech': { en: `Nothing counted for a minister from outside parliament (not confirmed).`, nl: `Niets meegeteld voor een minister van buiten het parlement (niet bevestigd).`, fr: `Rien n'est compté pour un ministre extérieur au Parlement (non confirmé).` },
  'tip.mpPension': { en: `Pension 8.80%`, nl: `Pensioen 8,80%`, fr: `Retraite 8,80%` },
  'tip.mpAfm': { en: `End-of-mandate fund`, nl: `Fonds einde mandaat`, fr: `Fonds de fin de mandat` },
