  'pol.stat.pm': { en: `Giorgia Meloni only gets her pay as an MP`, nl: `Giorgia Meloni krijgt alleen haar loon als parlementslid`, fr: `Giorgia Meloni ne touche que son indemnité de députée` },
  'pol.stat.tech': { en: `Pay set by law, without the tax-free daily allowance`, nl: `Loon uit de wet, zonder de belastingvrije dagvergoeding`, fr: `Indemnité fixée par la loi, sans l'indemnité de séjour exonérée` },
