  'pol.stat.pres': { en: `Sergio Mattarella, who lowered his own pay in 2022`, nl: `Sergio Mattarella, die zijn eigen toelage in 2022 verlaagde`, fr: `Sergio Mattarella, qui a réduit sa propre dotation en 2022` },
